// Health-risk example — the patient's side, compiled to WebAssembly.
//
// The same keygen / encrypt / decrypt as keygen.cpp, encrypt.cpp and
// decrypt.cpp, working on in-memory byte buffers instead of files, so it can
// run in a browser. The secret key lives only in this module's memory; there
// is no function that returns it.
//
// JavaScript API (embind):
//   keygen(ringDim)                  -> undefined   generates the context and all keys
//   setupFile(name)                  -> Uint8Array  "cc.bin" | "pk.bin" | "mk.bin" | "rk.bin"
//   checkInputs(male, age, bmi, sbp, treated, smoker, diabetic) -> ""  or the reason it is refused
//   encrypt(male, age, bmi, sbp, treated, smoker, diabetic)     -> Uint8Array (ct_x.bin)
//   decrypt(bytes)                   -> number      the 10-year risk as a fraction

#include "openfhe.h"

#include <emscripten/bind.h>
#include <emscripten/val.h>

#include <sstream>

#include "ciphertext-ser.h"
#include "cryptocontext-ser.h"
#include "key/key-ser.h"
#include "scheme/ckksrns/ckksrns-ser.h"

#include "../../common.hpp"

using namespace lbcrypto;
using namespace health_risk;
using emscripten::val;

namespace {

CryptoContext<DCRTPoly> g_cc;
KeyPair<DCRTPoly> g_keys;

val to_js(const std::string& bytes) {
    // Copy out of the wasm heap: the view would be invalidated by heap growth.
    val view(emscripten::typed_memory_view(bytes.size(), reinterpret_cast<const uint8_t*>(bytes.data())));
    val out = val::global("Uint8Array").new_(bytes.size());
    out.call<void>("set", view);
    return out;
}

void require_keys() {
    if (!g_cc) throw std::runtime_error("call keygen() first");
}

}  // namespace

void keygen(uint32_t ring_dim) {
    g_cc = make_context(ring_dim);
    g_keys = g_cc->KeyGen();
    g_cc->EvalMultKeyGen(g_keys.secretKey);
    g_cc->EvalRotateKeyGen(g_keys.secretKey, kRotations);
}

val setup_file(const std::string& name) {
    require_keys();
    std::ostringstream os;
    if (name == "cc.bin")
        Serial::Serialize(g_cc, os, SerType::BINARY);
    else if (name == "pk.bin")
        Serial::Serialize(g_keys.publicKey, os, SerType::BINARY);
    else if (name == "mk.bin")
        g_cc->SerializeEvalMultKey(os, SerType::BINARY);
    else if (name == "rk.bin")
        g_cc->SerializeEvalAutomorphismKey(os, SerType::BINARY);
    else
        throw std::runtime_error("not a setup file: " + name);  // never sk.bin
    return to_js(os.str());
}

std::string check_inputs(bool male, double age, double bmi, double sbp,
                         int treated, int smoker, int diabetic) {
    return out_of_range(Patient{male, age, bmi, sbp, treated, smoker, diabetic});
}

val encrypt(bool male, double age, double bmi, double sbp, int treated, int smoker, int diabetic) {
    require_keys();
    Patient p{male, age, bmi, sbp, treated, smoker, diabetic};
    if (auto why = out_of_range(p); !why.empty()) throw std::runtime_error(why);
    auto ct = g_cc->Encrypt(g_keys.publicKey, g_cc->MakeCKKSPackedPlaintext(pack(p)));
    std::ostringstream os;
    Serial::Serialize(ct, os, SerType::BINARY);
    return to_js(os.str());
}

double decrypt(const val& bytes) {
    require_keys();
    const auto data = emscripten::convertJSArrayToNumberVector<uint8_t>(bytes);
    std::istringstream is(std::string(data.begin(), data.end()));
    Ciphertext<DCRTPoly> ct;
    Serial::Deserialize(ct, is, SerType::BINARY);
    Plaintext pt;
    g_cc->Decrypt(g_keys.secretKey, ct, &pt);
    pt->SetLength(1);
    return pt->GetRealPackedValue()[0];
}

EMSCRIPTEN_BINDINGS(health_risk) {
    emscripten::function("keygen", &keygen);
    emscripten::function("setupFile", &setup_file);
    emscripten::function("checkInputs", &check_inputs);
    emscripten::function("encrypt", &encrypt);
    emscripten::function("decrypt", &decrypt);
}
